local function C_8()
	local script = LMG2L["LocalScript_8"];
	local button = script.Parent -- Scriptin butonun içinde olduğunu varsayıyoruz



	button.MouseButton1Click:Connect(function()

	    local player = game.Players.LocalPlayer

	    local tool = nil



	    -- F3X SyncAPI'yi bulma işlemi

	    for i,v in pairs(player:GetDescendants()) do

	        if v.Name == "SyncAPI" then

	            tool = v.Parent

	            break

	        end

	    end



	    if not tool then

	        for i,v in pairs(game.ReplicatedStorage:GetDescendants()) do

	            if v.Name == "SyncAPI" then

	                tool = v.Parent

	                break

	            end

	        end

	    end



	    -- Eğer F3X bulunamazsa işlemi durdurur

	    if not tool or not tool:FindFirstChild("SyncAPI") then 

	        warn("F3X Tool bulunamadı!")

	        return 

	    end



	    local remote = tool.SyncAPI.ServerEndpoint



	    -- API İstek Fonksiyonu

	    local function _(args)

	        remote:InvokeServer(unpack(args))

	    end



	    -- Kilidi Açma Fonksiyonu

	    local function SetLocked(part, boolean)

	        _( {"SetLocked", {part}, boolean} )

	    end



	    -- Doku Oluşturma Fonksiyonu

	    local function SpawnDecal(part, side)

	        local args = {

	            [1] = "CreateTextures",

	            [2] = {

	                [1] = {

	                    ["Part"] = part,

	                    ["Face"] = side,

	                    ["TextureType"] = "Decal"

	                }

	            }

	        }

	        _(args)

	    end



	    -- Dokuyu ID ile Güncelleme Fonksiyonu

	    local function AddDecal(part, asset, side)

	        local args = {

	            [1] = "SyncTexture",

	            [2] = {

	                [1] = {

	                    ["Part"] = part,

	                    ["Face"] = side,

	                    ["TextureType"] = "Decal",

	                    ["Texture"] = "rbxassetid://" .. asset

	                }

	            }

	        }

	        _(args)

	    end



	    -- Tüm Haritaya Yayma İşlemi (Spam)

	    local function spam(id)

	        for i, v in pairs(game.Workspace:GetDescendants()) do

	            if v:IsA("BasePart") then

	                task.spawn(function()

	                    SetLocked(v, false)

	                    -- Altı yüzeyin tamamına ekle

	                    local faces = Enum.NormalId:GetEnumItems()

	                    for _, face in pairs(faces) do

	                        SpawnDecal(v, face)

	                        AddDecal(v, id, face)

	                    end

	                end)

	            end

	        end

	    end



	    -- Senin verdiğin yeni ID: 137778054054297

	    spam("137778054054297")

	end)	
end;
